INSERT INTO ui_texts (key, screen, place, kind, ru, en, az, tr, "updatedAt") VALUES ('exchange.coinsFrozenNote', 'shop', 'exchange', 'label', 'Монеты заморожены. Покупатель оплатит TON на твой кошелёк — тогда сделка закроется. Не оплатит за 30 минут — монеты вернутся.', 'Coins are frozen. The buyer will send TON to your wallet — then the deal closes. No payment within 30 minutes and the coins come back.', 'Sikkələr dondurulub. Alıcı TON-u pul kisənizə göndərəcək — sövdələşmə onda bağlanır. 30 dəqiqə ərzində ödəməsə, sikkələr qayıdır.', 'Coinler donduruldu. Alıcı cüzdanınıza TON gönderecek — işlem o zaman kapanır. 30 dakika içinde ödemezse coinler geri döner.', now()) ON CONFLICT (key) DO UPDATE SET ru=EXCLUDED.ru, en=EXCLUDED.en, az=EXCLUDED.az, tr=EXCLUDED.tr, "updatedAt"=now();
